// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount) public {
        vm.assume(caller != address(0));
        vm.assume(depositAmount > 0 && depositAmount <= type(uint256).max / 2); // avoid overflow in balance sum

        // Fund the caller with enough Ether to deposit
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        (bool depositSuccess,) = address(c).call{value: depositAmount}("");
        require(depositSuccess, "Deposit failed");

        // Record balances before withdrawal
        uint256 callerBalanceBefore = c.balances(caller);
        uint256 callerEthBefore = caller.balance;

        // Call withdraw
        vm.prank(caller);
        (bool withdrawSuccess,) = address(c).call(abi.encodeWithSignature("withdraw()"));

        // The rule: if withdraw succeeds, the caller's Ether balance increases by exactly the amount in their balances mapping before the call
        if (withdrawSuccess) {
            uint256 callerEthAfter = caller.balance;
            assertTrue(callerEthAfter == callerEthBefore + callerBalanceBefore, "Withdraw did not transfer correct amount to caller");
        }
    }
}

